package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.ObjectCodec;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactory;
import com.fasterxml.jackson.core.sym.*;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for UTF8StreamJsonParser._parseFieldName
 */
public class UTF8StreamJsonParser__parseFieldName_TriageGen1Test {

    private UTF8StreamJsonParser parser;
    private byte[] inputBuffer;
    private IOContext ioc;
    private BytesToNameCanonicalizer sym;
    private ObjectCodec codec;

    private static final int INT_QUOTE = '"';

    @Before
    public void setUp() throws Exception {
        ioc = new IOContext();
        codec = new JsonFactory().getCodec();
        sym = new BytesToNameCanonicalizer();
        inputBuffer = new byte[128];
    }

    private void setupParser(byte[] data) throws Exception {
        InputStream is = new ByteArrayInputStream(data);
        parser = new UTF8StreamJsonParser(ioc, 0, is, codec, sym, inputBuffer, 0, data.length, false);

        // Use reflection to set the actual input buffer to our controlled array if needed, 
        // but the constructor already takes it. We ensure the internal state matches.
        setPrivateField(parser, "_inputBuffer", data);
        setPrivateField(parser, "_inputPtr", 0);
        setPrivateField(parser, "_inputEnd", data.length);
    }

    private void setPrivateField(Object obj, String fieldName, Object value) throws Exception {
        Field field = obj.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(obj, value);
    }

    private Name invokeParseFieldName(int i) throws Exception {
        Method method = UTF8StreamJsonParser.class.getDeclaredMethod("_parseFieldName", int.class);
        method.setAccessible(true);
        return (Name) method.invoke(parser, i);
    }

    @Test
    public void testHandleOddName() throws Exception {
        // If i != INT_QUOTE, it calls _handleOddName
        setupParser(new byte[]{0x5B}); // '['
        Name result = invokeParseFieldName(0x5B);
        assertNotNull(result);
    }

    @Test
    public void testSlowParseNameDueToBounds() throws Exception {
        // If i == INT_QUOTE and (_inputPtr + 9) > _inputEnd
        // We provide a buffer that is too short for the optimization
        byte[] smallBuffer = new byte[]{(byte) INT_QUOTE, 'a'};
        setupParser(smallBuffer);

        // This should trigger slowParseName()
        // Since we can't easily mock slowParseName without PowerMock, 
        // we observe the behavior (it will likely throw EOF or parse via slow path)
        try {
            invokeParseFieldName(INT_QUOTE);
        } catch (Exception e) {
            // Expected if slowParseName fails due to EOF
        }
    }

    @Test
    public void testEmptyName() throws Exception {
        // Case: q == INT_QUOTE (the "" case)
        // The code logic: q = input[_inputPtr++] & 0xFF; 
        // If q is quote, and it's the first char after the check
        byte[] data = new byte[]{(byte) INT_QUOTE, (byte) INT_QUOTE};
        setupParser(data);

        // To reach "if (q == INT_QUOTE)", the first byte read must be quote.
        // However, the code enters the 'if (codes[q] == 0)' block first if it's Latin1.
        // The "if (q == INT_QUOTE)" block is only reachable if codes[q] != 0 (non-Latin1) 
        // BUT the logic says "return parseName(0, q, 0)" if it's an invalid char.
        // Let's test the path where q is quote but somehow bypasses Latin1 check or is treated as such.
        // Actually, in ASCII, codes[quote] is 0. So it enters the nested if-statements.

        // Let's test the path: q = quote, then next i is quote -> findName(q, 1)
        byte[] data2 = new byte[]{(byte) INT_QUOTE, (byte) INT_QUOTE};
        setupParser(data2);
        Name result = invokeParseFieldName(INT_QUOTE);
        // Since codes[quote] == 0, it goes into the nested logic.
        // q = quote. i = quote. i == INT_QUOTE -> findName(q, 1)
    }

    @Test
    public void testParseNamePath1() throws Exception {
        // q = 'a', i = 'b', i == INT_QUOTE -> findName(q, 2)
        byte[] data = new byte[]{(byte) INT_QUOTE, 'a', 'b', (byte) INT_QUOTE};
        setupParser(data);
        Name result = invokeParseFieldName(INT_QUOTE);
        assertNotNull(result);
    }

    @Test
    public void testParseNamePath2() throws Exception {
        // q = 'a', i = 'b', i = 'c', i == INT_QUOTE -> findName(q, 3)
        byte[] data = new byte[]{(byte) INT_QUOTE, 'a', 'b', 'c', (byte) INT_QUOTE};
        setupParser(data);
        Name result = invokeParseFieldName(INT_QUOTE);
        assertNotNull(result);
    }

    @Test
    public void testParseNamePath3() throws Exception {
        // q = 'a', i = 'b', i = 'c', i = 'd', i == INT_QUOTE -> findName(q, 4)
        byte[] data = new byte[]{(byte) INT_QUOTE, 'a', 'b', 'c', 'd', (byte) INT_QUOTE};
        setupParser(data);
        Name result = invokeParseFieldName(INT_QUOTE);
        assertNotNull(result);
    }

    @Test
    public void testMediumNamePath() throws Exception {
        // q = 'a', i = 'b', i = 'c', i = 'd', i = 'e' -> parseMediumName
        byte[] data = new byte[]{(byte) INT_QUOTE, 'a', 'b', 'c', 'd', 'e', (byte) INT_QUOTE};
        setupParser(data);
        Name result = invokeParseFieldName(INT_QUOTE);
        assertNotNull(result);
    }

    @Test
    public void testNonLatin1Path() throws Exception {
        // To reach "if (q == INT_QUOTE)" at the bottom, codes[q] must be non-zero.
        // This requires a multi-byte UTF-8 sequence.
        // Let's simulate a character where codes[q] != 0.
        // For example, a high bit set.
        byte[] data = new byte[]{(byte) 0x80, (byte) INT_QUOTE}; 
        setupParser(data);

        // This will hit the last return: return parseName(0, q, 0);
        Name result = invokeParseFieldName(INT_QUOTE);
        assertNotNull(result);
    }

    @Test
    public void testParseNameWithLength1() throws Exception {
        // q = 'a', i = 'b' -> parseName(q, i, 1)
        byte[] data = new byte[]{(byte) INT_QUOTE, 'a', 'b', (byte) INT_QUOTE};
        // Note: the logic for 1 char is: q = input[ptr++], i = input[ptr++]. 
        // if (i == quote) return findName(q, 1).
        // If i is NOT quote, return parseName(q, i, 1).
        byte[] data2 = new byte[]{(byte) INT_QUOTE, 'a', 'b', 'c', (byte) INT_QUOTE};
        setupParser(data2);
        // q='a', i='b'. i is not quote. returns parseName('a', 'b', 1)
        Name result = invokeParseFieldName(INT_QUOTE);
        assertNotNull(result);
    }
}
